#include "ProjectPersistence.h"
static void testPersistence(const File& parent){
    auto root=parent.getChildFile("persistence-"+Uuid().toString());root.createDirectory();auto file=root.getChildFile(String::fromUTF8("Композиция.pulse"));auto backup=projectBackupFile(file);auto old=emptyProject();old.title="Last committed";old.patterns[0].lanes[7]={{0,1,60,.7f}};auto next=old;next.title="Candidate";next.patterns[0].lanes[7].push_back({2,1,67,.8f});
    expect(saveProject(old,file).wasOk()&&!backup.exists(),"first checked save validates and publishes a project without a fictitious backup");auto original=file.loadFileAsString();expect(saveProject(next,file).wasOk()&&backup.loadFileAsString()==original,"replacement keeps an exact previous project backup");Project read;expect(loadProject(file,read).wasOk()&&read.title==next.title&&read.patterns[0].lanes[7]==next.patterns[0].lanes[7],"checked save preserves exact musical content");
    auto priorBackup=backup.loadFileAsString();expect(saveProject(next,file).wasOk()&&backup.loadFileAsString()==priorBackup,"identical saves do not rotate away the previous distinct project");
    for(auto stage:{ProjectSaveStage::written,ProjectSaveStage::flushed,ProjectSaveStage::verified,ProjectSaveStage::backup,ProjectSaveStage::beforeCommit}){auto primary=file.loadFileAsString();ProjectSaveControl injected;injected.checkpoint=[stage](ProjectSaveStage at,const File&){return at==stage?Result::fail("Injected write/flush/verification/commit failure"):Result::ok();};expect(saveProjectChecked(old,file,&injected).failed()&&file.loadFileAsString()==primary&&loadProject(file,read).wasOk(),"every injected precommit failure retains the complete committed project");expect(loadProject(backup,read).wasOk(),"failed saves retain a valid previous generation");}
    auto primary=file.loadFileAsString(),previous=backup.loadFileAsString();for(int bad=0;bad<7;++bad){auto invalid=next;if(bad==0)invalid.tracks.clear();if(bad==1)invalid.patterns[0].lanes[7][0].pitch=128;if(bad==2)invalid.patterns[0].lanes[7][0].beat=-1;if(bad==3)invalid.patterns[0].length=65;if(bad==4)invalid.tracks[7].volume=-1;if(bad==5)invalid.activePattern=99;if(bad==6)invalid.patterns[0].length=2;expect(saveProject(invalid,file).failed()&&file.loadFileAsString()==primary&&backup.loadFileAsString()==previous,("invalid serialized case "+String(bad)+" cannot replace good saves").toRawUTF8());}
    ProjectSaveControl corrupt;corrupt.checkpoint=[](ProjectSaveStage at,const File& staged){if(at==ProjectSaveStage::verified)staged.replaceWithText("{truncated");return Result::ok();};expect(saveProjectChecked(old,file,&corrupt).failed()&&file.loadFileAsString()==primary,"staging corruption after initial verification is detected before replacement");
    ProjectSaveControl external;external.checkpoint=[&](ProjectSaveStage at,const File&){if(at==ProjectSaveStage::beforeCommit)file.replaceWithText(original);return Result::ok();};expect(saveProjectChecked(next,file,&external).failed()&&file.loadFileAsString()==original,"destination changes during save remain untouched by commit");
    saveProject(next,file);file.replaceWithText("{damaged latest");auto damaged=file.loadFileAsString();File used;auto sentinel=read;expect(loadProjectWithBackup(file,read,used).wasOk()&&used==backup&&read.title=="Last committed","damaged primary recovery falls back to its valid prior generation");expect(file.loadFileAsString()==damaged,"reading fallback leaves the damaged original available for diagnosis");ProjectSaveControl retry;retry.checkpoint=[](ProjectSaveStage at,const File&){return at==ProjectSaveStage::beforeCommit?Result::fail("Injected commit retry"):Result::ok();};bool retries=saveProjectChecked(read,file,&retry).failed()&&saveProjectChecked(read,file,&retry).failed();int copies=0;for(const auto& entry:RangedDirectoryIterator(root,false,file.getFileName()+".damaged-*",File::findFiles))copies+=entry.getFile().loadFileAsString()==damaged;expect(retries&&copies==1&&file.loadFileAsString()==damaged,"failed commit retries reuse one exact damaged-byte archive without accumulating duplicate files");expect(saveProject(read,file).wasOk()&&loadProject(file,read).wasOk()&&backup.loadFileAsString()==original,"refreshing a recovered project retains the last valid backup");bool retained=false;for(const auto& entry:RangedDirectoryIterator(root,false,file.getFileName()+".damaged-*",File::findFiles))retained|=entry.getFile().loadFileAsString()==damaged;expect(retained,"refresh preserves exact damaged bytes in a separate local file");
    file.replaceWithText("");expect(loadProjectWithBackup(file,read,used).wasOk()&&saveProject(read,file).wasOk(),"empty recovery files can fall back and be repaired without losing previous data");file.replaceWithText("{bad");backup.replaceWithText("{also bad");auto before=JSON::toString(projectToJson(read));auto usedBefore=used;expect(loadProjectWithBackup(file,read,used).failed()&&JSON::toString(projectToJson(read))==before&&used==usedBefore,"two damaged generations reject without changing the caller's project or source identity");file.deleteFile();backup.replaceWithText(original);expect(loadProjectWithBackup(file,read,used).failed(),"missing primary never resurrects a deliberately retired backup");
    auto unicode=root.getChildFile("utf16-project.pulse");unicode.replaceWithText(original,true,true);MemoryBlock utf16;unicode.loadFileAsData(utf16);expect(loadProject(unicode,read).wasOk()&&read.title==old.title,"bounded reader retains legacy BOM-marked UTF-16 project support");expect(saveProject(next,unicode).wasOk()&&projectBackupFile(unicode).getSize()==(int64)utf16.getSize()&&projectFileToken(projectBackupFile(unicode))==SHA256(utf16).toHexString(),"encoding migration preserves exact original UTF-16 bytes in the previous copy");
    auto blocked=root.getChildFile("blocked.pulse");blocked.createDirectory();expect(saveProject(next,blocked).failed()&&blocked.isDirectory(),"a directory at the save path cannot be replaced by a project");auto invalidParent=root.getChildFile("not-a-directory");invalidParent.replaceWithText("KEEP");expect(saveProject(next,invalidParent.getChildFile("song.pulse")).failed()&&invalidParent.loadFileAsString()=="KEEP","unwritable parent failure retains the original obstructing file");
    saveProject(next,file);primary=file.loadFileAsString();backup.deleteFile();backup.createDirectory();expect(saveProject(old,file).failed()&&file.loadFileAsString()==primary&&backup.isDirectory(),"unavailable backup destination prevents an unsafe primary overwrite");
}
static int persistenceProbe(int argc,char** argv){
    if(argc!=4)return 2;File root(String::fromUTF8(argv[2]));root.createDirectory();auto mode=String::fromUTF8(argv[3]);auto file=root.getChildFile("song.pulse");auto project=emptyProject();project.title=mode=="seed"?"Last committed":"Candidate";project.patterns[0].lanes[7]={{0,1,mode=="seed"?60:67,.8f}};ProjectSaveControl probe;
    const char* names[]={"written","flushed","verified","backup","beforeCommit","committed"};probe.checkpoint=[&](ProjectSaveStage stage,const File& staged){if(mode==names[(int)stage]){auto marker=root.getChildFile("probe-reached.txt");marker.replaceWithText(staged.getFullPathName());for(;;)Thread::sleep(100);}return Result::ok();};return saveProjectChecked(project,file,&probe).wasOk()?0:3;
}
